import {problem,orderedProblem,formatValue} from './validation.mjs';
import {costBreakdown,validateResourceIssue,seedResources} from './resources.mjs';
export const evidence = {hypothesis:{label:'Hypotese',rank:1},benchmark:{label:'Benchmark',rank:2},observational:{label:'Observasjon',rank:3},quasi:{label:'Kvasi-eksperiment',rank:4},randomized:{label:'Randomisert',rank:5}};
export const strategicFit = {low:{label:'Lav',rank:1},medium:{label:'Middels',rank:2},high:{label:'Høy',rank:3}};
export const horizons = {now:{label:'Now',window:'0–3 mnd',rank:1},next:{label:'Next',window:'3–12 mnd',rank:2},later:{label:'Later',window:'12+ mnd',rank:3}};
const baseExamples = [
 {id:'diagnostics',name:'Proaktiv diagnostikk',description:'Oppdag og løs bredbåndsproblemer før kunden tar kontakt. Prioriter kunder med gjentatte avbrudd.',segment:'Bredbånd · gjentatte feil',customers:100000,reach:80,baseline:10,low:.2,expected:.6,high:1,value:6000,cost:900000,setup:200000,confidence:'quasi',evidence:'Illustrasjon: Et mulig kvasi-eksperiment med sammenlignbare områder før og etter utrulling. Ingen faktisk studie ligger bak tallene. Kontroller parallelle trender, feilmønster og forskjeller i kundemiks.',strategicFit:'high',strategicFitNote:'Illustrativt: Understøtter uttalt prioritet om færre bredbåndsfeil før kunden merker dem. Vurderingen påvirker ikke nettoverdien.',horizon:'now',requires:['telemetry'],keyResultIds:['kr-churn','kr-repeat']},
 {id:'wifi',name:'Bedre Wi-Fi-opplevelse',description:'Bedre dekning og stabilitet gjennom optimalisering, veiledning og målrettede tiltak i hjemmet.',segment:'Wi-Fi · svak dekning',customers:160000,reach:65,baseline:9,low:.1,expected:.4,high:.8,value:6000,cost:1200000,setup:400000,confidence:'observational',evidence:'Illustrativt observasjonsgrunnlag. Sammenheng mellom Wi-Fi-kvalitet og churn kan skyldes bolig, utstyr, kundemiks og engasjement. Den kausale effekten må testes.',strategicFit:'medium',strategicFitNote:'Illustrativt: Relevant for kundeopplevelsen, men ikke forankret i et navngitt strategisk initiativ ennå.',horizon:'next',requires:[],keyResultIds:['kr-coverage']},
 {id:'parental',name:'Foreldrekontroll',description:'Enklere skjermtidsstyring og tryggere nett for familier med barn.',segment:'Familier · barn i husstanden',customers:75000,reach:35,baseline:7,low:-.1,expected:.25,high:.6,value:5500,cost:450000,setup:100000,confidence:'hypothesis',evidence:'Illustrativ hypotese uten målt churn-effekt. Lavscenarioet inkluderer mulig økt churn. Test behov, aktivering og bruk før en kontrollert utrulling.',strategicFit:'low',strategicFitNote:'Illustrativt: Sidespor fra kjernesatsingen på bredbånd og Wi-Fi-kvalitet. Vurder om dette bør konkurrere med tiltak nærmere strategien.',horizon:'later',requires:[],keyResultIds:[]},
 {id:'adoption',name:'Mitt WiFi-adopsjon',description:'Øk aktiv bruk av Mitt WiFi gjennom onboarding og relevant hjelp i kundereisen.',segment:'App · nye og inaktive brukere',customers:200000,reach:45,baseline:8,low:0,expected:.3,high:.5,value:6000,cost:400000,setup:100000,confidence:'benchmark',evidence:'Illustrativt benchmark, ikke en dokumentert effekt. Mer engasjerte kunder kan både bruke appen og ha lavere churn. Ikke tolk bruker/ikke-bruker-forskjellen som kausal.',strategicFit:'medium',strategicFitNote:'Illustrativt: Støtter appstrategien, men er ikke identifisert som et av årets hovedinitiativ.',horizon:'next',requires:[],keyResultIds:['kr-churn']},
 {id:'telemetry',name:'Felles telemetriplattform',description:'Samle og standardisere telemetri fra rutere og nett, med tilgangsstyring, slik at andre tiltak kan bruke dataene.',segment:'Plattform · ingen direkte kundeeffekt',customers:0,reach:0,baseline:10,low:0,expected:0,high:0,value:6000,cost:300000,setup:500000,confidence:'hypothesis',evidence:'Illustrativt: Plattformarbeid uten egen churn-effekt. Verdien ligger i tiltakene det gjør mulig, ikke i tiltaket selv.',strategicFit:'high',strategicFitNote:'Illustrativt: Forutsetning for datadrevet feilretting. Alene ser tiltaket ulønnsomt ut; se hva det låser opp.',horizon:'now',requires:[],keyResultIds:[]}
];
export const examples=baseExamples.map(seedResources);
export function calculate(t, reduction=t.expected, costCase='expected'){const exposed=t.customers*t.reach/100;const retained=exposed*reduction/100;const gross=retained*t.value;const cost=costBreakdown(t,costCase).total;return {exposed,retained,gross,cost,net:gross-cost,roi:cost>0?(gross-cost)/cost*100:null,churn:t.baseline-reduction,breakEven:exposed*t.value>0?cost/(exposed*t.value)*100:null};}
export function validate(t){return validateIssue(t)?.message??'';}
export function validateIssue(t){
 const fail=(message,...fields)=>problem(message,'main',null,fields);
 if(!t.name?.trim())return fail('Gi tiltaket et navn.','name');
 const labels={customers:'Adresserbare kunder',reach:'Rekkevidde',baseline:'Baseline churn',value:'Dekningsbidrag per beholdt kunde',low:'Lav churn-reduksjon',expected:'Forventet churn-reduksjon',high:'Høy churn-reduksjon',cost:'Årlig kostnad',setup:'Engangskostnad'};
 for(const key of Object.keys(labels))if(!Number.isFinite(t[key]))return fail(`${labels[key]}: skriv inn et gyldig tall.`,key);
 if(t.customers<0||!Number.isInteger(t.customers))return fail('Adresserbare kunder må være et heltall som er 0 eller større.','customers');
 if(t.productCustomers!==undefined&&(!Number.isInteger(t.productCustomers)||t.productCustomers<0||t.customers>t.productCustomers))return fail(`Adresserbare kunder kan ikke overstige produktets kundebase (${formatValue(t.productCustomers)}). Korriger kundeanslaget eller produktinnstillingen.`,'customers');
 for(const key of ['value','cost','setup'])if(t[key]<0)return fail(`${labels[key]} kan ikke være negativ.`,key);
 for(const key of ['reach','baseline'])if(t[key]<0||t[key]>100)return fail(`${labels[key]} må være mellom 0 og 100 %.`,key);
 const order=orderedProblem(t,'Churn-reduksjon',fail,{nonnegative:false,unit:'pp'});if(order)return order;
 if(t.high>t.baseline)return fail(`Høy churn-reduksjon (${formatValue(t.high)} pp) overstiger baseline (${formatValue(t.baseline)} %). Reduser høyt anslag eller korriger baseline, slik at churn ikke blir negativ.`,'high','baseline');
 if(t.low<t.baseline-100)return fail('Lav churn-reduksjon gir churn over 100 %. Korriger lavt anslag eller baseline.','low','baseline');
 if(!evidence[t.confidence])return fail('Velg et gyldig evidensnivå.','confidence');
 if(!strategicFit[t.strategicFit])return fail('Velg en gyldig strategisk fit.','strategicFit');
 if(t.horizon&&!horizons[t.horizon])return fail('Velg en gyldig tidshorisont, eller la feltet stå tomt for et tiltak som ikke er plassert ennå.','horizon');
 if((t.requires??[]).includes(t.id))return fail('Et tiltak kan ikke forutsette seg selv. Fjern koblingen.','requires');
 return validateResourceIssue(t);
}
export const costCaseFor=key=>key==='low'?'high':key==='high'?'low':'expected';
export function scenario(t,key='expected'){return calculate(t,t[key],costCaseFor(key));}
export function sortMeasures(items,key){const score=t=>key==='confidence'?evidence[t.confidence].rank:key==='strategicFit'?strategicFit[t.strategicFit].rank:key==='low'?scenario(t,'low').net:key==='roi'?(calculate(t).roi??-Infinity):key==='retained'?calculate(t).retained:calculate(t).net;return [...items].sort((a,b)=>score(b)-score(a)||calculate(b).net-calculate(a).net||a.name.localeCompare(b.name,'nb'));}
